static char *
sanitize_team_config(const char *config)
{
    char *ret;
    int   i;

    if (!config)
        return NULL;

    ret = g_strdup(config);

    for (i = 0; i < strlen(ret); i++) {
        if (ret[i] == '\n')
            ret[i] = ' ';
    }

    return ret;
}

